class ActivationBlock {HHOOK hook_;public:ActivationBlock(){hook_=SetWindowsHookEx(WH_CBT,[](int n,WPARAM w,LPARAM l)->LRESULT{return n==HCBT_ACTIVATE?1:CallNextHookEx(nullptr,n,w,l);},nullptr,GetCurrentThreadId());if(!hook_)throw std::runtime_error("Cannot isolate reuse fixture");}~ActivationBlock(){UnhookWindowsHookEx(hook_);}};
bool Reject(const std::function<void()>& f){try{f();return false;}catch(const std::exception&){return true;}}
sct::core::DocumentState Source(int width=128,int height=96){using namespace sct::core;Image image;image.Create(width,height);for(int y=0;y<height;++y)for(int x=0;x<width;++x){auto* p=image.Row(y)+x*4;p[0]=BYTE(x%251);p[1]=BYTE(y%251);p[2]=17;p[3]=255;}auto state=Document(std::move(image)).State();for(int i=0;i<3;++i){Annotation a;a.tool=Tool::Rectangle;a.rect={10+i*30,10,30+i*30,30};a.label=CString(wchar_t('A'+i));a.group=i?7:0;a.color=RGB(230,20,40);state.objects.push_back(a);}return state;}
bool Clear(const sct::core::Image& image){return std::all_of(image.pixels.begin(),image.pixels.end(),[](BYTE b){return b==0;});}
