 auto object=core::ObjectTemplate(source,{1});check(object.base!=source.base&&Clear(*object.base)&&object.objects.size()==2&&object.objects[0].label==L"B"&&object.objects[0].group==7,"object template contains only selected expanded objects over newly cleared transparent pixels");std::vector<BYTE> bytes;CString error;core::DocumentState loaded;check(services::EncodeProject(object,bytes,error)&&services::DecodeProject(bytes,loaded,error)&&Clear(*loaded.base)&&loaded.objects.size()==2,"existing bounded project format round trips template privacy and editable fields");auto target=Source(16,16);auto imported=core::ImportTemplate(target,loaded,ids);check(imported.base->width==128&&imported.base->height==96&&imported.objects.size()==5&&ids==core::composition::Indices({3,4}),"template import expands right/bottom and returns all appended objects");check(imported.objects[3].group==imported.objects[4].group&&imported.objects[3].group!=7&&imported.objects[1].group==7&&imported.base->Row(0)[2]==17&&imported.base->Row(90)[120*4]==255,"template import remaps colliding groups and preserves old pixels with white expansion");
 auto image=Source(7,5).base;const auto rectangles=core::ImageGrid(7,5,3,2);const auto tiles=core::SplitGrid(*image,3,2);std::vector<int> coverage(35);bool exact=tiles.size()==6;for(size_t i=0;i<tiles.size();++i){const auto r=rectangles[i];exact=exact&&tiles[i].pixels==image->Crop(r).pixels;for(int y=r.top;y<r.bottom;++y)for(int x=r.left;x<r.right;++x)++coverage[y*7+x];}check(exact&&std::all_of(coverage.begin(),coverage.end(),[](int n){return n==1;}),"uneven grid tiles preserve exact RGBA and cover every source pixel once in reading order");check(Reject([]{core::ImageGrid(7,5,1,1);})&&Reject([]{core::ImageGrid(7,5,17,1);})&&Reject([]{core::ImageGrid(2,2,3,2);})&&Reject([]{core::ImageGrid(32768,32768,2,2);}),"empty/oversized/excessive grids reject before pixel allocation");
