 static EditorFrame* Page(EditorWorkspace& w){auto* p=new EditorFrame(Source(),L"",&w,true);p->cursorApplyAudit_=[](LPCTSTR){};w.pages_.push_back(p);w.active_=0;w.ResumePage(p);w.RefreshDocuments();w.Layout();Wait(p);p->dirty_=false;return p;}
 static void Reset(EditorFrame* p,int width=128,int height=96){Wait(p);p->FinishText(false);p->CancelCrop();p->pixelSelection_.SetRectEmpty();p->document_.Reset(Source(width,height));p->selected_=-1;p->selectedObjects_.clear();p->style_=core::Annotation{};p->style_.tool=core::Tool::Select;p->tools_.SetCurSel(static_cast<int>(p->style_.tool));p->Changed();p->SyncStyle();p->Layout();Wait(p);p->dirty_=false;}
